import sys

def distance(a, b):
    d = 0
    while a != b:
        if a > b:
            a //= 2
        else:
            b //= 2
        d += 1
    return d

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    out = []
    idx = 1
    for _ in range(n):
        i = int(data[idx]); j = int(data[idx+1])
        idx += 2
        out.append(str(distance(i, j)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

